81	  constructor(message: string, exitCode: number = 1) {
82	    super(message);
83	    this.name = 'EvalRunError';
84	    // POSIX exit codes are 1-255 (0 means success). Coerce silly values to the
85	    // default rather than letting `exitCode = 0` silently mask a real failure.
86	    this.exitCode = Number.isInteger(exitCode) && exitCode >= 1 && exitCode <= 255 ? exitCode : 1;
87	  }
88	}
